// ============================================
// AI-basierte Preisverarbeitung v8 (ScrapingBee)
// ============================================

const items = $input.all();
let ean = '';
let produktname = '';

try {
  const originalData = $('Set Data').first().json;
  ean = originalData.ean || '';
  produktname = originalData.produktname || '';
} catch (e) {
  console.log('Set Data nicht verfuegbar');
}

const result = {
  ean: ean,
  produktname: produktname,
  timestamp: new Date().toLocaleString('de-DE'),
  shopPrices: {},
  cheapestShop: null,
  cheapestPrice: null,
  totalShopsFound: 0,
  ignoredItems: []
};

// Minimaler Preis fuer Motorsaegen (filtert Zubehoer)
const MIN_PRICE = 200;
const MAX_PRICE = 5000;

// Verarbeite AI-Ergebnisse
for (const item of items) {
  const data = item.json;

  if (!data || data.gefunden === false || data.error) {
    continue;
  }

  // Preispiraten hat mehrere Preise
  if (data.preise && Array.isArray(data.preise)) {
    for (const p of data.preise) {
      if (!p.preis || p.preis < MIN_PRICE || p.preis > MAX_PRICE) {
        if (p.preis) result.ignoredItems.push(`${p.shop}: ${p.preis} Euro (zu niedrig)`);
        continue;
      }

      if (p.shop && p.verfuegbar !== false) {
        const shopKey = p.shop.toLowerCase().replace(/[^a-z]/g, '');
        if (!result.shopPrices[shopKey] || p.preis < result.shopPrices[shopKey].price) {
          result.shopPrices[shopKey] = {
            name: p.shop,
            price: p.preis,
            produkt: p.produkt || ''
          };
        }
      }
    }
  }

  // Ignorierte Items aus Preispiraten
  if (data.ignoriert && Array.isArray(data.ignoriert)) {
    result.ignoredItems = result.ignoredItems.concat(data.ignoriert);
  }

  // Einzelne Shop-Ergebnisse (von ScrapingBee)
  if (data.shop && data.preis && data.gefunden && data.verfuegbar !== false) {
    if (data.preis < MIN_PRICE || data.preis > MAX_PRICE) {
      result.ignoredItems.push(`${data.shop}: ${data.preis} Euro (ausserhalb Bereich)`);
      continue;
    }

    const shopKey = data.shop.toLowerCase().replace(/[^a-z]/g, '');
    if (!result.shopPrices[shopKey] || data.preis < result.shopPrices[shopKey].price) {
      result.shopPrices[shopKey] = {
        name: data.shop,
        price: data.preis,
        produkt: data.produkt_gefunden || ''
      };
    }
  }
}

// Finde guenstigsten
let cheapestPrice = Infinity;
for (const key of Object.keys(result.shopPrices)) {
  const shop = result.shopPrices[key];
  if (shop.price < cheapestPrice) {
    cheapestPrice = shop.price;
    result.cheapestShop = shop.name;
    result.cheapestPrice = shop.price;
  }
}

result.totalShopsFound = Object.keys(result.shopPrices).length;

if (result.totalShopsFound === 0) {
  result.warning = 'Keine Preise fuer Motorsaege gefunden';
}

return [{ json: result }];

const p = $input.first().json;

if (!p.ean) {
  return [];
}

const today = new Date().toLocaleDateString('de-DE');
const formatPrice = (price) => price ? price.toFixed(2).replace('.', ',') : '';
const getPrice = (key) => formatPrice(p.shopPrices?.[key]?.price);

const output = {
  Datum: today,
  EAN: p.ean,
  Produktname: p.produktname || '',
  Lohmeier: getPrice('lohmeier'),
  Motorland: getPrice('motorland'),
  Agrieuro: getPrice('agrieuro'),
  Simon: getPrice('simonprofi') || getPrice('simon'),
  Otto: getPrice('otto'),
  Amazon: getPrice('amazon'),
  eBay: getPrice('ebay'),
  Kaufland: getPrice('kaufland'),
  Idealo: getPrice('idealo'),
  Galaxus: getPrice('galaxus'),
  Conrad: getPrice('conrad'),
  ManoMano: getPrice('manomano'),
  Guenstigster_Shop: p.cheapestShop || '',
  Guenstigster_Preis: formatPrice(p.cheapestPrice),
  Anzahl_Shops: p.totalShopsFound,
  Hinweis: p.warning || ''
};

return [{ json: output }];
